    /* ==========================================================================
       2. GLOBAL STATE MANAGEMENT
       ========================================================================== */
    let currentLang = 'en';
    let currentStageIndex = 0; // 0 to 7
    let selectedDiamondShape = 'pear'; // 'oval', 'pear', 'emerald', 'round', 'cushion'
    let cadAngle='side';
    let fixedCadAngle=false;
    const cadImages={"side": "assets/customisation/27ef07f47c6b.webp", "profile": "assets/customisation/14354c559306.webp", "underside": "assets/customisation/ae1f8605fd55.webp"};

    let cadViewMode='3d'; // '3d' or '2d'
    let threeScene, threeCamera, threeRenderer, diamondMesh, ringGroup;
    let isThreeInitialized = false;

    // Direct Hash Links Mapping
    const hashToStage=Object.fromEntries(i18n.en.stages.map((stage,index)=>[stage.hash,index]));

    /* ==========================================================================
       3. INITIALIZATION ON WINDOW LOAD
       ========================================================================== */
    window.addEventListener('popstate',()=>{currentStageIndex=hashToStage[location.hash]??0;updateStageView()});
    window.onload = function() {
      // 1. Build Stationary Stage Dial Nodes
      renderStationaryDialNodes();
      
      // 2. Build Bottom Roadmap
      renderRoadmap();

      // 3. Initialize Three.js WebGL Scene inside Loupe
      try { initThreeJS(); } catch (error) { console.warn("WebGL unavailable",error); }

      // 4. Check initial URL hash for direct links like #cad
      const initialHash = window.location.hash.toLowerCase();
      if (hashToStage[initialHash] !== undefined) {
        currentStageIndex = hashToStage[initialHash];
      }

      // 5. Render active stage view
      updateStageView();

      // 6. Listen for keyboard navigation (Left / Right Arrow Keys)
      window.addEventListener('keydown', handleKeyPress);
      
      // 7. Touch Swipe Support for Loupe Container
      setupTouchSwipe();
    };

    /* ==========================================================================
       4. STATIONARY DIAL NODE RENDERING
       Stage numbers (1-8) remain STRICTLY UPRIGHT while orbiting the ring.
       ========================================================================== */
    function renderStationaryDialNodes() {
      const container = document.getElementById('dial-nodes-container');
      container.innerHTML = '';

      const totalStages = 8;
      // Angle positions starting from top (-90 deg)
      const radius = 44; // Percentage radius

      for (let i = 0; i < totalStages; i++) {
        const angle = (i * (360 / totalStages) - 90) * (Math.PI / 180);
        // Calculate X and Y percentages (50% center offset)
        const left = 50 + radius * Math.cos(angle);
        const top = 50 + radius * Math.sin(angle);

        const node = document.createElement('button');
        node.id = `dial-node-${i}`;
        node.onclick = () => setStage(i);
        node.className = `dial-node absolute transform -translate-x-1/2 -translate-y-1/2 w-9 h-9 sm:w-11 sm:h-11 rounded-full bg-emerald-950 border border-gold-600/40 text-gold-400 font-bold text-xs sm:text-sm flex items-center justify-center transition-all duration-300 z-20 hover:scale-110 hover:border-gold-300`;
        node.style.left = `${left}%`;
        node.style.top = `${top}%`;

        // Number element inside node is non-rotated (STATIONARY)
        node.innerHTML = `<span>${i + 1}</span>`;

        container.appendChild(node);
      }
    }

    /* ==========================================================================
       5. ROADMAP STRIP AT BOTTOM
       ========================================================================== */
    function renderRoadmap() {
      const container = document.getElementById('roadmap-container');
      container.innerHTML = '';

      const stagesData = i18n[currentLang].stages;
      stagesData.forEach((st, idx) => {
        const item = document.createElement('button');
        item.onclick = () => setStage(idx);
        item.id = `roadmap-item-${idx}`;
        item.className = `p-2 rounded-lg border text-left transition-all ${idx === currentStageIndex ? 'bg-emerald-900/80 border-gold-500 text-gold-300' : 'bg-emerald-950/40 border-gold-600/10 text-slate-400 hover:border-gold-600/30'}`;
        item.innerHTML = `
          <div class="text-[9px] font-mono text-gold-600 uppercase">${currentLang==='zh'?'步驟':'STEP'} 0${idx + 1}</div>
          <div class="text-xs font-medium truncate">${st.name}</div>
        `;
        container.appendChild(item);
      });
    }

    /* ==========================================================================
       6. STAGE STATE SWITCHER & HASH SYNC
       ========================================================================== */
    function setStage(index) {
      if (index < 0 || index > 7) return;
      currentStageIndex = index;
      
      // Sync URL hash without triggering scroll shift
      const hash = i18n.en.stages[currentStageIndex].hash;
      if (location.hash===hash) {updateStageView();return;}
      if (history.pushState) {
        history.pushState(null, null, hash);
      } else {
        location.hash = hash;
      }

      updateStageView();
    }

    function previousStage() {
      const prev = (currentStageIndex - 1 + 8) % 8;
      setStage(prev);
    }

    function nextStage() {
      const next = (currentStageIndex + 1) % 8;
      setStage(next);
    }

    function handleKeyPress(e) {
      if (e.key === 'ArrowLeft') previousStage();
      if (e.key === 'ArrowRight') nextStage();
      if (e.key >= '1' && e.key <= '8') {
        setStage(parseInt(e.key) - 1);
      }
    }

    /* ==========================================================================
       7. UPDATE VIEW & DYNAMIC STAGE CONTROLS
       ========================================================================== */
    function updateStageView() {
      document.getElementById('bespoke-guide').textContent=currentLang==='zh'?'訂製珠寶指南':'Bespoke design guide';
      document.documentElement.lang=currentLang==='zh'?'zh-HK':'en';
      document.querySelectorAll('[data-copy]').forEach(el=>el.textContent=label(el.dataset.copy));
      const langData = i18n[currentLang];
      const stageInfo = langData.stages[currentStageIndex];

      // 1. Header Navigation Highlights
      for (let i = 0; i < 8; i++) {
        const navEl = document.getElementById(`nav-stage-${i}`);
        if (navEl) {
          navEl.textContent=(i+1)+'. '+langData.stages[i].name;navEl.href=langData.stages[i].hash;
          if (i === currentStageIndex) {
            navEl.className = 'text-gold-400 font-bold border-b border-gold-500 pb-0.5 transition-colors';
          } else {
            navEl.className = 'hover:text-gold-400 transition-colors text-slate-400 font-medium';
          }
        }
      }

      // 2. Stationary Dial Active Node Update
      for (let i = 0; i < 8; i++) {
        const node = document.getElementById(`dial-node-${i}`);
        if (node) {
          if (i === currentStageIndex) {
            node.classList.add('active', 'bg-gold-500', 'text-emerald-950', 'scale-110');
            node.classList.remove('bg-emerald-950', 'text-gold-400');
          } else {
            node.classList.remove('active', 'bg-gold-500', 'text-emerald-950', 'scale-110');
            node.classList.add('bg-emerald-950', 'text-gold-400');
          }
        }
      }

      // 3. Update Arc Glow Angle
      const glowArc = document.getElementById('dial-glow-arc');
      if (glowArc) {
        glowArc.style.strokeDasharray = `${currentStageIndex * 12.5} 100`;
      }

      // 4. Update Card Text
      document.getElementById('stage-counter-txt').innerText = `${currentLang==='zh'?'階段':'STAGE'} ${currentStageIndex + 1} / 8`;
      document.getElementById('stage-badge-tag').innerText = stageInfo.tag;
      document.getElementById('stage-title').innerText = stageInfo.title;
      document.getElementById('stage-description').innerText = stageInfo.desc;
      document.getElementById('loupe-hud-tag').innerText = currentStageIndex===3 ? (currentLang==='zh'?'CAD 檢視':'CAD view') : stageInfo.hud;

      // Update Primary Action Button
      const primaryBtn = document.getElementById('stage-primary-action');
      primaryBtn.querySelector('span').innerText = stageInfo.actionText;

      // Update WhatsApp link with current stage query
      const waBtn = document.getElementById('stage-whatsapp-action');
      waBtn.href = "https://wa.me/447594442577";

      // 5. Update Bottom Roadmap
      renderRoadmap();

      // 6. Update Loupe Display based on active stage
      renderLoupeContent();
    }

    /* ==========================================================================
       8. LOUPE CONTENT CONTROLLER (WebGL 3D vs 2D Canvas vs Photography)
       ========================================================================== */
    const zhLabels={"SELECT LOOSE DIAMOND CUT SHAPE:": "選擇裸鑽形狀", "PEAR": "梨形", "OVAL": "橢圓形", "ROUND": "圓形", "EMERALD": "祖母綠形", "CUSHION": "枕形", "CAD VIEW MODE:": "設計圖檢視模式", "3D Model": "3D 模型", "CAD reference views": "CAD 參考圖", "CAMERA ANGLE PRESETS:": "選擇觀看角度", "Side View": "側面", "Profile View": "輪廓", "Underside View": "底部"};
    function label(en){return currentLang==="zh" ? (zhLabels[en] || en) : en;}
    function renderLoupeContent() {
      const canvas3D = document.getElementById('loupeCanvas3D');
      const imgContainer = document.getElementById('stageImageContainer');
      const badge3D = document.getElementById('badge3DModel');

      // Hide all overlays by default
      canvas3D.style.display = 'none';
      imgContainer.style.opacity = '0';
      badge3D.classList.add('hidden');

      const interactiveBox = document.getElementById('stage-interactive-controls');
      interactiveBox.innerHTML = '';
      const stage = i18n[currentLang].stages[currentStageIndex];
      imgContainer.style.backgroundColor = '';
      if (stage.note) {
        const note=document.createElement('div');
        note.className='stage-note';
        const heading=document.createElement('strong');
        heading.textContent=stage.note;
        const copy=document.createElement('p');
        copy.textContent=stage.detail;
        note.append(heading,copy);
        interactiveBox.append(note);
      }

      switch (currentStageIndex) {

        // ---------------- STAGE 1: Loose Diamonds (3D Diamond Refraction) ----------------
        case 0:
          if (!isThreeInitialized) {
            imgContainer.style.opacity='1';imgContainer.innerHTML='';
            imgContainer.style.backgroundImage='url(assets/customisation/a3788754195b.webp)';imgContainer.style.backgroundSize='cover';break;
          }
          canvas3D.style.display = 'block';
          if (diamondMesh && ringGroup) {
            diamondMesh.visible = true;
            ringGroup.visible = false;
          }
          
          // Build shape switcher controls inside card
          interactiveBox.insertAdjacentHTML('beforeend', `
            <div class="text-xs font-semibold text-gold-400 mb-2">${label("SELECT LOOSE DIAMOND CUT SHAPE:")}</div>
            <div class="grid grid-cols-5 gap-1.5 text-[10px] font-medium text-center">
              <button onclick="changeDiamondShape('pear')" class="p-2 rounded-lg border ${selectedDiamondShape === 'pear' ? 'bg-gold-500 text-emerald-950 font-bold border-gold-300' : 'bg-emerald-900/60 border-gold-600/30 text-slate-300'}">${label("PEAR")}</button>
              <button onclick="changeDiamondShape('oval')" class="p-2 rounded-lg border ${selectedDiamondShape === 'oval' ? 'bg-gold-500 text-emerald-950 font-bold border-gold-300' : 'bg-emerald-900/60 border-gold-600/30 text-slate-300'}">${label("OVAL")}</button>
              <button onclick="changeDiamondShape('round')" class="p-2 rounded-lg border ${selectedDiamondShape === 'round' ? 'bg-gold-500 text-emerald-950 font-bold border-gold-300' : 'bg-emerald-900/60 border-gold-600/30 text-slate-300'}">${label("ROUND")}</button>
              <button onclick="changeDiamondShape('emerald')" class="p-2 rounded-lg border ${selectedDiamondShape === 'emerald' ? 'bg-gold-500 text-emerald-950 font-bold border-gold-300' : 'bg-emerald-900/60 border-gold-600/30 text-slate-300'}">${label("EMERALD")}</button>
              <button onclick="changeDiamondShape('cushion')" class="p-2 rounded-lg border ${selectedDiamondShape === 'cushion' ? 'bg-gold-500 text-emerald-950 font-bold border-gold-300' : 'bg-emerald-900/60 border-gold-600/30 text-slate-300'}">${label("CUSHION")}</button>
            </div>
            
          `);
          break;

        // ---------------- STAGE 2: Quote & Deposit (Quiet Text & Price Breakdown) ----------------
        case 3:
          if(!isThreeInitialized && cadViewMode==='3d') cadViewMode='2d';
          if (cadViewMode === '3d') {
            canvas3D.style.display = 'block';
            badge3D.classList.remove('hidden');
            if (diamondMesh && ringGroup) {
              diamondMesh.visible = false;
              ringGroup.visible = true;
            }
          } else {
            imgContainer.style.opacity='1';
            imgContainer.style.backgroundImage='none';
            imgContainer.style.backgroundColor='#2d2d2b';
            const reference=new Image();
            reference.alt=label({side:'Side View',profile:'Profile View',underside:'Underside View'}[cadAngle]);
            reference.className='cad-reference';
            reference.src=cadImages[cadAngle];
            imgContainer.replaceChildren(reference);
          }

          interactiveBox.innerHTML = `
            <div class="space-y-3">
              <div class="flex items-center justify-between">
                <span class="text-xs font-semibold text-gold-400">${label("CAD VIEW MODE:")}</span>
                <div class="flex gap-1 bg-emerald-900 p-1 rounded-lg border border-gold-600/30 text-[10px]">
                  <button onclick="setCADMode('3d')" class="px-3 py-1 rounded ${cadViewMode === '3d' ? 'bg-gold-500 text-emerald-950 font-bold' : 'text-slate-300'}">${label("3D Model")}</button>
                  <button onclick="setCADMode('2d')" class="px-3 py-1 rounded ${cadViewMode === '2d' ? 'bg-gold-500 text-emerald-950 font-bold' : 'text-slate-300'}">${label("CAD reference views")}</button>
                </div>
              </div>

              <div class="text-[11px] font-semibold text-slate-300">${label("CAMERA ANGLE PRESETS:")}</div>
              <div class="grid grid-cols-3 gap-2 text-center text-[10px]">
                <button onclick="setRingAngle('side')" class="py-1.5 rounded bg-emerald-900/80 hover:bg-emerald-800 border border-gold-600/30 text-gold-400">${label("Side View")}</button>
                <button onclick="setRingAngle('profile')" class="py-1.5 rounded bg-emerald-900/80 hover:bg-emerald-800 border border-gold-600/30 text-gold-400">${label("Profile View")}</button>
                <button onclick="setRingAngle('underside')" class="py-1.5 rounded bg-emerald-900/80 hover:bg-emerald-800 border border-gold-600/30 text-gold-400">${label("Underside View")}</button>
              </div>
            </div>
          `;
          if(cadViewMode==='2d'){
            const open=document.createElement('button');
            open.className='mt-3 underline text-gold-400 text-xs';
            open.textContent=currentLang==='zh'?'放大參考圖':'Enlarge reference';
            open.onclick=()=>{
              const dialog=document.getElementById('cad-zoom');
              const image=dialog.querySelector('img');
              image.src=cadImages[cadAngle];image.alt=imgContainer.querySelector('img').alt;
              dialog.querySelector('button').textContent=currentLang==='zh'?'關閉':'Close';
              dialog.showModal();
            };
            interactiveBox.append(open);
          }
          break;

        // ---------------- STAGE 4: Production (Jeweller at Bench Visual) ----------------
        case 4: {
          const image=new Image();
          image.alt='';
          image.style.cssText='width:100%;height:100%;object-fit:cover';
          image.src='images/bespoke-hand-setting.webp';
          imgContainer.replaceChildren(image);
          imgContainer.style.opacity='1';
          break;
        }
        default: {
          const panel=document.createElement('div');
          panel.className='lens-stage';
          const title=document.createElement('strong');
          title.textContent=stage.name;
          const detail=document.createElement('span');
          detail.textContent=stage.note;
          panel.append(title,detail);
          imgContainer.replaceChildren(panel);
          imgContainer.style.opacity='1';
        }
      }
    }

    /* ==========================================================================
       9. THREE.JS 3D ENGINE INITIALIZATION (Diamond & Solitaire Ring)
       ========================================================================== */
    function initThreeJS() {
      const container = document.getElementById('loupeCanvas3D');
      const width = container.clientWidth || 280;
      const height = container.clientHeight || 280;

      threeScene = new THREE.Scene();
      
      threeCamera = new THREE.PerspectiveCamera(45, width / height, 0.1, 1000);
      threeCamera.position.set(0, 0, 7);

      threeRenderer = new THREE.WebGLRenderer({ canvas: container, alpha: true, antialias: true });
      threeRenderer.outputEncoding=THREE.sRGBEncoding;
      threeRenderer.setSize(width, height,false);
      const frame=container.parentElement;
      const resizeLoupe=()=>{
        const size=frame.clientWidth;
        if(!size) return;
        threeRenderer.setPixelRatio(Math.min(3,Math.max(2,window.devicePixelRatio)));
        threeRenderer.setSize(size,frame.clientHeight,false);
        threeCamera.aspect=size/frame.clientHeight;threeCamera.updateProjectionMatrix();
      };
      new ResizeObserver(resizeLoupe).observe(frame);resizeLoupe();

      // Lighting Setup for Brilliant Diamond Sparkle
      const ambientLight = new THREE.AmbientLight(0xffffff, .45);
      threeScene.add(ambientLight);

      const keyLight = new THREE.DirectionalLight(0xfff5ea, 1.3);
      keyLight.position.set(5, 5, 5);
      threeScene.add(keyLight);

      const goldRimLight = new THREE.DirectionalLight(0xffe1b0, .6);
      goldRimLight.position.set(-5, -5, -2);
      threeScene.add(goldRimLight);

      const topLight = new THREE.PointLight(0xffffff, 2.0, 10);
      topLight.position.set(0, 4, 2);
      threeScene.add(topLight);

      // Create 3D Loose Diamond Mesh
      createDiamondMesh(selectedDiamondShape);

      // Create 3D Solitaire Ring Mesh
      createSolitaireRingMesh();

      isThreeInitialized = true;

      // Mouse Drag Orbit Controls
      setupCanvasControls(container);

      // Animation Loop
      function animate() {
        requestAnimationFrame(animate);

        // Auto Rotation when not actively dragging
        if (diamondMesh && diamondMesh.visible) {
          diamondMesh.rotation.y += 0.008;
          
        }

        if (ringGroup && ringGroup.visible && !fixedCadAngle && !isDragging) {
          ringGroup.rotation.y += 0.005;
        }

        if(!document.hidden && (currentStageIndex===0 || (currentStageIndex===3 && cadViewMode==='3d'))) threeRenderer.render(threeScene, threeCamera);
      }
      animate();
    }

    /* Create 3D Loose Diamond Procedural Geometry */
    // Each stone has a table, angled crown, narrow girdle and tapered pavilion.
    function cutGeometry(shape) {
      const step = shape === 'emerald';
      const count = step ? 8 : 32;
      const corners = [[.66,1],[-.66,1],[-1,.68],[-1,-.68],[-.66,-1],[.66,-1],[1,-.68],[1,.68]];
      function point(i, radius, height, offset=0) {
        const angle = 2*Math.PI*(i+offset)/count;
        let x = Math.cos(angle), z = Math.sin(angle);
        if (step) [x,z] = corners[i%8];
        if (shape === 'cushion') {x=Math.sign(x)*Math.pow(Math.abs(x),.66);z=Math.sign(z)*Math.pow(Math.abs(z),.66);}
        if (shape === 'pear') {x*=1-.46*z; z*=1.43;}
        if (shape === 'oval' || step) z*=1.36;
        return [x*radius,height,z*radius];
      }
      const tiers = step ? [[.65,.33],[.82,.23],[1,.04],[1,0],[.79,-.23],[.49,-.44],[.12,-.62]] :
        [[.55,.34],[.78,.22],[1,.035],[1,0],[.68,-.24],[.025,-.71]];
      const vertices=[];
      function facet(a,b,c){vertices.push(...a,...b,...c);}
      tiers.forEach(([r,h],k)=>{
        const ring = i=>point(i,r,h,!step && k===1 ? .5 : 0);
        for(let i=0;i<count;i++){
          const a=ring(i),b=ring(i+1);
          if(k===0)facet([0,h,0],b,a);
          if(k===tiers.length-1){facet([0,h-.01,0],a,b);continue;}
          const [nr,nh]=tiers[k+1];
          const c=point(i,nr,nh,!step && k===0?.5:0),d=point(i+1,nr,nh,!step && k===0?.5:0);
          facet(a,b,c);facet(b,d,c);
        }
      });
      const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));g.computeVertexNormals();return g;
    }
    // High-contrast softboxes reflected and refracted across individual facet planes.
    function gemMaterial(){
      return new THREE.ShaderMaterial({
        vertexShader:`varying vec3 local; varying vec3 n; varying vec3 p; void main(){local=position;n=normalize(mat3(modelMatrix)*normal);p=(modelMatrix*vec4(position,1.)).xyz;gl_Position=projectionMatrix*viewMatrix*vec4(p,1.);}`,
        fragmentShader:`varying vec3 local; varying vec3 n; varying vec3 p;
        float studio(vec3 d){float bands=.5+.5*cos(10.*atan(d.x,d.z)+4.*d.y);return .12+.72*smoothstep(.28,.76,bands)+.35*smoothstep(.28,.8,d.y);}
        void main(){vec3 N=normalize(n),V=normalize(cameraPosition-p);
        vec3 ray=refract(-V,N,1./2.417);vec3 bounce=reflect(ray,normalize(vec3(-N.x,-.72,-N.z)));
        vec2 section=local.xz+.12*ray.xz;
        float theta=atan(section.y,section.x);float slice=6.283185/16.;
        float index=floor(theta/slice);float f=fract(theta/slice);
        float inner=step(length(section),.48*(1.-abs(2.*f-1.)));
        float axis=(index+.5)*slice+inner*.21;
        vec3 pavilion=normalize(vec3(cos(axis),-.77,sin(axis)));
        float core=studio(reflect(ray,pavilion));
        float body=mix(studio(bounce),core,.72),rim=pow(1.-abs(dot(N,V)),3.);
        vec3 light=vec3(body)*vec3(.96,.985,1.)+.14*vec3(studio(bounce+.055),studio(bounce),studio(bounce-.055));
        gl_FragColor=vec4(mix(light,vec3(studio(reflect(-V,N))),.23+.45*rim),1.);}`
      });
    }
    function createDiamondMesh(shape){
      if(diamondMesh){threeScene.remove(diamondMesh);diamondMesh.geometry.dispose();diamondMesh.material.dispose();}
      diamondMesh=new THREE.Mesh(cutGeometry(shape),gemMaterial());
      diamondMesh.scale.setScalar(1.52);diamondMesh.rotation.set(.78,.25,-.18);threeScene.add(diamondMesh);
    }

    /* Change Loose Diamond Cut Shape */
    function changeDiamondShape(shape) {
      selectedDiamondShape = shape;
      if(isThreeInitialized) createDiamondMesh(shape);
      renderLoupeContent();
    }

